import gurobipy
from gurobipy import GRB

def solve_problem():
    table_id = 'file_0_view_0'
    tables = CSVQA_DATA.get('tables', [])
    target_table = None
    for tbl in tables:
        if tbl.get('table_id') == table_id:
            target_table = tbl
            break
    if target_table is None:
        raise ValueError(f"Table with id '{table_id}' not found in CSVQA_DATA")
    records = target_table.get('records', [])
    if not records:
        raise ValueError(f"No records found in table '{table_id}'")
    g = {}
    c = {}
    for rec in records:
        vals = rec.get('values', {})
        option = vals.get('option')
        if option is None:
            raise ValueError("Record missing 'option' field")
        if option in g:
            raise ValueError(f"Duplicate option '{option}' found in data")
        try:
            gen_per_lot = float(vals.get('gen_per_lot'))
            cost_per_lot = float(vals.get('cost_per_lot'))
        except (TypeError, ValueError) as e:
            raise ValueError(f"Invalid numeric value for option '{option}': {e}")
        g[option] = gen_per_lot
        c[option] = cost_per_lot
    O = list(g.keys())
    m = gurobipy.Model()
    m.setParam('MIPGap', 1e-06)
    x = m.addVars(O, vtype=GRB.INTEGER, lb=0, name='')
    m.setObjective(gurobipy.quicksum((c[o] * x[o] for o in O)), GRB.MINIMIZE)
    m.addConstr(gurobipy.quicksum((g[o] * x[o] for o in O)) >= 200, name='generation_requirement')
    m.optimize()
    if m.Status == GRB.OPTIMAL:
        print(f'ObjVal: {m.ObjVal}')
        for var in m.getVars():
            print(f'{var.VarName}: {var.X}')
    else:
        print(f'Solver status: {m.Status}')
    return m
m = solve_problem()
